# Emit public/data/results-lite.json — a light overlay of finishing
# positions/statuses keyed by site event id + bib, for career-page badges.
# Coverage: events linked through filming_calendar (event_id + site_slug both
# set) — which is every filmed event from now on, automatically, via the
# daily refresh chain. Regenerated by catalog_refresh after link_calendar.
import io, json, os

try:
    import truststore; truststore.inject_into_ssl()
except ImportError:
    pass
import psycopg2

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
PLATFORM_ENV = r"C:\Users\Equireel 1\Documents\equireel_clean\xc-start-times\.env"

url = os.environ.get("DATABASE_URL")
if not url and os.path.exists(PLATFORM_ENV):
    for line in io.open(PLATFORM_ENV, encoding="utf-8-sig"):
        if line.startswith("DATABASE_URL="):
            url = line.split("=", 1)[1].strip(); break

conn = psycopg2.connect(url)
conn.set_session(readonly=True, autocommit=True)
cur = conn.cursor()

cur.execute("""SELECT DISTINCT fc.site_slug, fc.event_id FROM filming_calendar fc
               WHERE fc.site_slug IS NOT NULL AND fc.event_id IS NOT NULL""")
links = cur.fetchall()

out = {}
rows_total = 0
for slug, ev_id in links:
    cur.execute("""SELECT bib_number, position, status_code FROM results
                   WHERE event_id=%s AND (position IS NOT NULL OR status_code IS NOT NULL)""",
                (ev_id,))
    ev = {}
    for bib, pos, status in cur.fetchall():
        b = "".join(ch for ch in str(bib or "") if ch.isdigit()) or str(bib or "")
        if not b:
            continue
        ev[b] = [pos, (status or "").strip()[:12] or None]
    if ev:
        out[slug] = ev
        rows_total += len(ev)

cur.close(); conn.close()
path = os.path.join(ROOT, "public", "data", "results-lite.json")
json.dump(out, io.open(path, "w", encoding="utf-8"), separators=(",", ":"))
print(f"results-lite.json: {len(out)} events, {rows_total} results")
